import{_ as s,c as n,o as e,aN as t}from"./chunks/framework.DUf1V_IZ.js";const b=JSON.parse('{"title":"Temperature、Top-p 与 Top-k","description":"","frontmatter":{"date":"2026-07-31T14:00:00.000Z","title":"Temperature、Top-p 与 Top-k","permalink":"/pages/t0pk03","categories":["AI"]},"headers":[],"relativePath":"AI/07.采样参数/Temperature与Top-p与Top-K.md","filePath":"AI/07.采样参数/Temperature与Top-p与Top-K.md","lastUpdated":1785478230000}'),p={name:"AI/07.采样参数/Temperature与Top-p与Top-K.md"};function o(r,a,l,i,d,c){return e(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="temperature、top-p-与-top-k" tabindex="-1">Temperature、Top-p 与 Top-k <a class="header-anchor" href="#temperature、top-p-与-top-k" aria-label="Permalink to &quot;Temperature、Top-p 与 Top-k&quot;">​</a></h1><h2 id="一、它们解决什么问题" tabindex="-1">一、它们解决什么问题 <a class="header-anchor" href="#一、它们解决什么问题" aria-label="Permalink to &quot;一、它们解决什么问题&quot;">​</a></h2><p>大模型生成文本是<strong>逐 Token 自回归</strong>的：每生成一个 Token，模型先输出一个覆盖整个词表（vocab）的<strong>对数几率（logits）</strong>，经过 Softmax 变成每个候选 Token 的<strong>概率分布</strong>，再从分布里&quot;抽&quot;出一个 Token 作为输出。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型输出 logits ──▶ Softmax ──▶ 概率分布 ──▶ 【采样策略】──▶ 选中一个 Token</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>Temperature</code>、<code>Top-p</code>、<code>Top-k</code> 都属于<strong>解码（decoding）阶段的采样参数</strong>，作用是：<strong>在最终&quot;抽哪个 Token&quot;这一步，怎么去调整那个概率分布、限制候选范围、控制随机性</strong>。</p><blockquote><p>关键点：这三个参数<strong>不改模型的权重，也不改变模型&quot;知道什么&quot;</strong>，只影响&quot;在已知的概率分布上怎么挑下一个字&quot;。调它们 = 调生成的随机度与多样性。</p></blockquote><hr><h2 id="二、temperature-温度" tabindex="-1">二、Temperature（温度） <a class="header-anchor" href="#二、temperature-温度" aria-label="Permalink to &quot;二、Temperature（温度）&quot;">​</a></h2><h3 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h3><p>Temperature 在 Softmax <strong>之前</strong>对 logits 做缩放：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p_i = exp(z_i / T) / Σ exp(z_j / T)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><code>z_i</code>：第 i 个 Token 的 logit</li><li><code>T</code>：温度值</li></ul><h3 id="直观效果" tabindex="-1">直观效果 <a class="header-anchor" href="#直观效果" aria-label="Permalink to &quot;直观效果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>T 取值</th><th>分布形状</th><th>生成表现</th></tr></thead><tbody><tr><td><strong>T → 0</strong>（趋近 0）</td><td>分布被&quot;压&quot;成只有一个尖峰</td><td>趋近<strong>贪心解码（Greedy）</strong>：永远选概率最高的词，几乎确定、重复、保守</td></tr><tr><td><strong>T = 1</strong></td><td>原分布不变</td><td>忠实反映模型原始判断</td></tr><tr><td><strong>T &gt; 1</strong>（如 1.5~2）</td><td>分布被&quot;摊平&quot;，高低概率差距缩小</td><td>更随机、更多样、更有创意，但容易胡说、跑题</td></tr><tr><td><strong>T &lt; 1</strong>（如 0.2~0.7）</td><td>分布更&quot;尖锐&quot;</td><td>更聚焦、更严谨、更确定</td></tr></tbody></table><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T 小（聚焦）              T 大（发散）</span></span>
<span class="line"><span>  ▲                         ▲</span></span>
<span class="line"><span>  │   ██                    │     ▆▆</span></span>
<span class="line"><span>  │  ████                   │    ▆▆▆▆</span></span>
<span class="line"><span>  │ ██████                  │   ▆▆▆▆▆▆</span></span>
<span class="line"><span>  │████████                 │  ▆▆▆▆▆▆▆▆</span></span>
<span class="line"><span>  └──────────▶             └──────────▶  候选 Token</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><blockquote><p>记忆：<strong>温度越低越&quot;轴&quot;（认死理、保守），温度越高越&quot;飘&quot;（发散、创意但易跑偏）。</strong></p></blockquote><hr><h2 id="三、top-k-按数量截断" tabindex="-1">三、Top-k（按数量截断） <a class="header-anchor" href="#三、top-k-按数量截断" aria-label="Permalink to &quot;三、Top-k（按数量截断）&quot;">​</a></h2><h3 id="原理-1" tabindex="-1">原理 <a class="header-anchor" href="#原理-1" aria-label="Permalink to &quot;原理&quot;">​</a></h3><p>不做任何缩放，而是<strong>只保留概率最高的 k 个 Token</strong>，把其余所有 Token 的概率置 0（或 -∞），重新归一化后再采样。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>原始分布（词表很大）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   │  只保留前 k 个 ──▶ [top1, top2, ..., topk]  ──▶ 重新归一化 ──▶ 采样</span></span>
<span class="line"><span>   │  其余全部剔除</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li><code>k = 1</code>：等价于贪心解码（永远选第一名）。</li><li><code>k</code> 很小（如 10~40）：候选极少，输出稳定、可控，但可能缺乏变化。</li><li><code>k</code> 很大（如 100+）：退化成&quot;几乎不截断&quot;，多样性上升但可能把低质量词也放进来。</li></ul><h3 id="局限" tabindex="-1">局限 <a class="header-anchor" href="#局限" aria-label="Permalink to &quot;局限&quot;">​</a></h3><p>Top-k 是<strong>固定数量截断</strong>，不灵活：</p><ul><li>当分布很&quot;尖&quot;（某个词概率极高）时，第 k 名可能已经是莫名其妙的次要词，却被强行纳入。</li><li>当分布很&quot;平&quot;（多个词概率接近）时，只取 k 个又可能漏掉一批同样合理的候选。</li></ul><p>于是有了更聪明的 <strong>Top-p</strong>。</p><hr><h2 id="四、top-p-核采样-nucleus-sampling" tabindex="-1">四、Top-p（核采样 / Nucleus Sampling） <a class="header-anchor" href="#四、top-p-核采样-nucleus-sampling" aria-label="Permalink to &quot;四、Top-p（核采样 / Nucleus Sampling）&quot;">​</a></h2><h3 id="原理-2" tabindex="-1">原理 <a class="header-anchor" href="#原理-2" aria-label="Permalink to &quot;原理&quot;">​</a></h3><p>按概率<strong>从高到低排序</strong>，取<strong>累计概率刚好达到 p 的最小 Token 集合</strong>（这个集合叫&quot;核 / nucleus&quot;），把集合之外的 Token 全部剔除，再归一化采样。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按概率降序排列：</span></span>
<span class="line"><span>  tokA 0.4 │</span></span>
<span class="line"><span>  tokB 0.25│</span></span>
<span class="line"><span>  tokC 0.15│</span></span>
<span class="line"><span>  tokD 0.10│</span></span>
<span class="line"><span>  tokE 0.05│</span></span>
<span class="line"><span>  ... 其余很小</span></span>
<span class="line"><span></span></span>
<span class="line"><span>设 p = 0.9：</span></span>
<span class="line"><span>  累计：0.4 → 0.65 → 0.80 → 0.90 ✅ 到此停止</span></span>
<span class="line"><span>  ⇒ 核 = {tokA, tokB, tokC, tokD}，其余全部剔除后归一化采样</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><ul><li><code>p = 1.0</code>：不截断，等于在所有 Token 上采样。</li><li><code>p</code> 越小（如 0.7~0.9）：核越小，越聚焦高概率词。</li><li><code>p</code> 越大（接近 1）：候选越多，越发散。</li></ul><h3 id="相比-top-k-的优势" tabindex="-1">相比 Top-k 的优势 <a class="header-anchor" href="#相比-top-k-的优势" aria-label="Permalink to &quot;相比 Top-k 的优势&quot;">​</a></h3><p>Top-p 是<strong>按分布形状动态截断</strong>：</p><ul><li>分布尖时，核自动很小（只留真正高概率的几个词）。</li><li>分布平时，核自动更大（把一批旗鼓相当的候选都纳入）。</li></ul><p>所以 Top-p 比 Top-k 更&quot;自适应&quot;，是现在的主流默认（很多 API 用 <code>top_p</code> 而非 <code>top_k</code>）。</p><hr><h2 id="五、三者如何组合-典型解码流水线" tabindex="-1">五、三者如何组合（典型解码流水线） <a class="header-anchor" href="#五、三者如何组合-典型解码流水线" aria-label="Permalink to &quot;五、三者如何组合（典型解码流水线）&quot;">​</a></h2><p>实际推理时，这三个参数往往<strong>串联</strong>起作用，标准顺序是：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>logits</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 1. ÷ Temperature  （缩放分布形状）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>  Softmax 概率分布</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─ 2. Top-k 截断     （先按数量砍掉太靠后的候选，作为安全上限）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>  ├─ 3. Top-p 截断     （再按累计概率砍，保留&quot;核&quot;）</span></span>
<span class="line"><span>  ▼</span></span>
<span class="line"><span>  └─ 4. 从最终候选里随机采样 ──▶ 输出一个 Token</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><ul><li><strong>Temperature</strong> 决定&quot;分布是尖还是平&quot;（整体随机基调）。</li><li><strong>Top-k</strong> 是一道&quot;硬性数量护栏&quot;（防止极端情况下把一堆垃圾词放进来）。</li><li><strong>Top-p</strong> 是&quot;柔性动态护栏&quot;（按分布自适应保留核心候选）。</li></ul><blockquote><p>工程实践：多数框架<strong>先 temperature，再 top_k（可选），再 top_p</strong>。也有说法建议 temperature 和 top_p <strong>二选一调</strong>，不要同时大幅改动，否则随机性叠加难预期。常见稳妥组合：<code>temperature=0.7~1.0</code> + <code>top_p=0.9</code> + <code>top_k=40~50</code>。</p></blockquote><hr><h2 id="六、参数怎么选-场景速查" tabindex="-1">六、参数怎么选（场景速查） <a class="header-anchor" href="#六、参数怎么选-场景速查" aria-label="Permalink to &quot;六、参数怎么选（场景速查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐设置</th><th>理由</th></tr></thead><tbody><tr><td>代码生成、事实问答、SQL/JSON 等确定性输出</td><td><code>temperature</code> 低（0~0.3），<code>top_p</code> 低（0.1~0.5）</td><td>要准确、可复现，少创意</td></tr><tr><td>通用对话、摘要</td><td><code>temperature</code> 0.7 左右，<code>top_p</code> 0.8~0.95</td><td>平衡准确与流畅</td></tr><tr><td>创意写作、头脑风暴、诗歌</td><td><code>temperature</code> 0.8~1.2，<code>top_p</code> 0.9~1.0</td><td>鼓励多样与新颖</td></tr><tr><td>需要完全可复现（评测/调试）</td><td><code>temperature=0</code>（贪心）或固定随机种子</td><td>消除随机性</td></tr><tr><td>翻译</td><td><code>temperature</code> 低（0~0.3）</td><td>翻译要忠实，不宜发挥</td></tr></tbody></table><hr><h2 id="七、常见误区" tabindex="-1">七、常见误区 <a class="header-anchor" href="#七、常见误区" aria-label="Permalink to &quot;七、常见误区&quot;">​</a></h2><p><strong>误区 1：Temperature 越高模型越&quot;聪明&quot;</strong> 错。温度只调随机性，不增加知识。温度过高只会让它更爱胡编（幻觉更多），不会更聪明。</p><p><strong>误区 2：Top-k 比 Top-p 更先进，应该只用 Top-k</strong> 恰恰相反。Top-p（核采样）因自适应截断，通常是更优的默认；Top-k 多作为&quot;数量护栏&quot;配合 Top-p 使用。</p><p><strong>误区 3：temperature 和 top_p 同时拉满能得到&quot;又准又活&quot;的效果</strong> 随机性会叠加，结果往往不可控。建议<strong>二选一主调</strong>，另一个保持默认或不动。</p><p><strong>误区 4：调这些参数能改变模型&quot;懂不懂&quot;</strong> 不能。它们只影响&quot;在已知分布上怎么挑下一个字&quot;。模型不会的内容，调再高温度也编不出来（只会编得更花）。</p><hr><h2 id="八、一句话总结" tabindex="-1">八、一句话总结 <a class="header-anchor" href="#八、一句话总结" aria-label="Permalink to &quot;八、一句话总结&quot;">​</a></h2><ul><li><strong>Temperature</strong>：把概率分布&quot;压尖&quot;或&quot;摊平&quot;，控制整体随机基调。</li><li><strong>Top-k</strong>：只在前 k 个最高概率词里选，固定数量护栏。</li><li><strong>Top-p（核采样）</strong>：只在累计概率达 p 的最小集合里选，自适应动态护栏。</li><li>三者串联：<strong>先温度缩放 → 再 Top-k 截断 → 再 Top-p 截断 → 采样</strong>。</li></ul><blockquote><p>口诀：<strong>温度定基调，k 限数量，p 圈核心；低温求稳、高温求变，核采样自适应最靠谱。</strong></p></blockquote>`,55)])])}const h=s(p,[["render",o]]);export{b as __pageData,h as default};
